#include "stm32f4xx.h"

//Definicion de variable 
volatile uint8_t incremento = 0; //variable para mirar el incremento de cada vez que se preciona el boton

//definicion de cabeceras - headers
void init_gpio();
void init_tim3();
void init_exti13();

