/**/
void init_gpio(){
    //clock signal for PC.
    //Activando la señal de reloj para el GPIOC
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOCEN; //Limpiando la posicion
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN; //Activando la señal

    //Configurando el pin C13
    GPIOC->MODER &= ~(0b11 << GPIO_MODER_MODE13_Pos); //Limpiando la posicion y queda como entrada 
    GPIOC->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD13_Pos); //Limpia, desactiva las PUPDR

}


void init_exti13(){
    //Señal de reloj SYSCONFIG, se debe mirar cual es el bus en el que esta conectado 
    RCC->APB2ENR &= ~ RCC_APB2ENR_SYSCFGEN; //Limpiar la señal de SYSCFG
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; //Activando la señal de reloj del SYSCFG

    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI13; //Limpiar la seleccion de puerto parala linea 13 
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI13_PC; //Ponemos 0010 en en puerto C y en la posicion 13, para decir que la linea EXTI13 viene del puerto  C 


    //Detectar solo flanco de bajada 
    EXTI->RTSR &= ~EXTI_RTSR_TR13; //Ponemos cero en la posicion 0, sin disparo de falnco de subida
    EXTI->FTSR &= ~ EXTI_FTSR_TR13; //Limpiamos la posicion, ponemos un cero 
    EXTI->FTSR |= EXTI_FTSR_TR13; //Ponemos 1 en la posicion 13, para configurarlo como flanco de bajada 


    EXTI->SWIER &= ~EXTI_SWIER_SWIER13;// Ponemos 0 en la posicion 13

    EXTI->IMR &= ~EXTI_IMR_IM13;// Limpiamos la posicion 13 
    EXTI->IMR |= EXTI_IMR_IM13;//Ponemos 1 en la posicion 13

    __NVIC_EnableIRQ (EXTI15_10_IRQn);//Habilitar en NVIC la interrupcion 

}

void EXTI15_10_IRQHandler (void){
    if (EXTI->PR & EXTI_PR_PR13) { //Verificar si la linea 13 genero la interrupcion
        EXTI->PR |= EXTI_PR_PR13; //Limpiar la bandera 

        incremento++; //sumamos 1 a la variable

    }
}


